window.OTTER2_STORYSUB = window.OTTER2_STORYSUB || {};
window.OTTER2_STORYSUB["1"] = {"hsk1-01": {"dur": 76.97, "cues": [[8.2, 12.164, "今天我去学校，认识一个好朋友。", "Jīn Tiān Wǒ Qù Xué Xiào, Rèn Shi Yí Gè Hǎo Péng Yǒu.", "Hôm nay tôi đến trường và quen một người bạn tốt."], [12.167, 15.747, "我叫李明。我今年二十岁。", "Wǒ Jiào Lǐ Míng. Wǒ Jīn Nián Èr Shí Suì.", "Tôi tên là Lý Minh. Năm nay tôi hai mươi tuổi."], [15.747, 19.063, "我是学生，我住在北京。", "Wǒ Shì Xué Shēng, Wǒ Zhù Zài Běi Jīng.", "Tôi là học sinh và sống ở Bắc Kinh."], [19.067, 22.983, "我的好朋友叫大卫，他也是学生。", "Wǒ De Hǎo Péng Yǒu Jiào Dà Wèi, Tā Yě Shì Xué Shēng.", "Bạn tốt của tôi tên là Đại Vệ, cậu ấy cũng là học sinh."], [23.0, 25.884, "我在学校学习汉语。", "Wǒ Zài Xué Xiào Xué Xí Hàn Yǔ.", "Tôi học tiếng Trung ở trường."], [25.884, 29.7, "上午我们一起上课，我很高兴。", "Shàng Wǔ Wǒ Men Yì Qǐ Shàng Kè, Wǒ Hěn Gāo Xìng.", "Buổi sáng chúng tôi học cùng nhau, tôi rất vui."], [29.7, 33.424, "我喜欢看书，也喜欢听音乐。", "Wǒ Xǐ Huan Kàn Shū, Yě Xǐ Huan Tīng Yīn Yuè.", "Tôi thích đọc sách và cũng thích nghe nhạc."], [33.433, 36.677, "大卫问我：你喜欢什么？", "Dà Wèi Wèn Wǒ: Nǐ Xǐ Huan Shén Me?", "Đại Vệ hỏi tôi: Bạn thích gì?"], [36.677, 39.657, "我说：我喜欢汉语。", "Wǒ Shuō: Wǒ Xǐ Huan Hàn Yǔ.", "Tôi nói: Tôi thích tiếng Trung."], [39.667, 43.103, "我写汉字，写错了一个字。", "Wǒ Xiě Hàn Zì, Xiě Cuò Le Yí Gè Zì.", "Tôi viết chữ Hán, viết sai một chữ."], [43.103, 46.847, "大卫帮助我，我说：谢谢你。", "Dà Wèi Bāng Zhù Wǒ, Wǒ Shuō: Xiè Xie Nǐ.", "Đại Vệ giúp tôi, tôi nói: Cảm ơn bạn."], [46.847, 48.987, "下午我回家。", "Xià Wǔ Wǒ Huí Jiā.", "Chiều tôi về nhà."], [48.987, 51.703, "妈妈问我今天好吗。", "Mā Ma Wèn Wǒ Jīn Tiān Hǎo Ma.", "Mẹ hỏi hôm nay tôi có ổn không."], [51.713, 55.245, "我说很好，我学习汉语了。", "Wǒ Shuō Hěn Hǎo, Wǒ Xué Xí Hàn Yǔ Le.", "Tôi nói rất tốt, tôi đã học tiếng Trung."], [55.245, 58.729, "妈妈说：李明，你很好。", "Mā Ma Shuō: Lǐ Míng, Nǐ Hěn Hǎo.", "Mẹ nói: Lý Minh, con rất giỏi."], [58.747, 62.399, "晚上我们一起吃饭，也很高兴。", "Wǎn Shàng Wǒ Men Yì Qǐ Chī Fàn, Yě Hěn Gāo Xìng.", "Buổi tối chúng tôi ăn cơm cùng nhau và cũng rất vui."], [62.399, 66.771, "妈妈说：你有好朋友，妈妈很高兴。", "Mā Ma Shuō: Nǐ Yǒu Hǎo Péng Yǒu, Mā Ma Hěn Gāo Xìng.", "Mẹ nói: Con có bạn tốt, mẹ rất vui."]]}, "hsk1-02": {"dur": 76.27, "cues": [[7.003, 10.343, "我家不大，可是很舒服。", "Wǒ Jiā Bú Dà, Kě Shì Hěn Shū Fu.", "Nhà tôi không lớn nhưng rất thoải mái."], [10.343, 12.843, "我家有四口人。", "Wǒ Jiā Yǒu Sì Kǒu Rén.", "Nhà tôi có bốn người."], [12.843, 16.471, "爸爸是老师，妈妈是医生。", "Bà Ba Shì Lǎo Shī, Mā Ma Shì Yī Shēng.", "Bố là giáo viên, mẹ là bác sĩ."], [16.471, 19.259, "爸爸妈妈工作很忙。", "Bà Ba Mā Ma Gōng Zuò Hěn Máng.", "Bố mẹ đi làm rất bận."], [19.277, 23.117, "姐姐是大学生，我是中学生。", "Jiě Jie Shì Dà Xué Shēng, Wǒ Shì Zhōng Xué Shēng.", "Chị là sinh viên, tôi là học sinh cấp hai."], [23.117, 26.697, "姐姐问我：你喜欢学校吗？", "Jiě Jie Wèn Wǒ: Nǐ Xǐ Huan Xué Xiào Ma?", "Chị hỏi tôi: Em có thích trường không?"], [26.697, 29.605, "我说：我很喜欢。", "Wǒ Shuō: Wǒ Hěn Xǐ Huan.", "Tôi nói: Em rất thích."], [29.617, 33.293, "晚上我们一起吃饭，都很高兴。", "Wǎn Shàng Wǒ Men Yì Qǐ Chī Fàn, Dōu Hěn Gāo Xìng.", "Buổi tối chúng tôi ăn cơm cùng nhau và đều rất vui."], [33.317, 36.321, "星期六我们不去学校。", "Xīng Qī Liù Wǒ Men Bú Qù Xué Xiào.", "Thứ Bảy chúng tôi không đến trường."], [36.321, 40.237, "早上我们一起吃面包，喝牛奶。", "Zǎo Shàng Wǒ Men Yì Qǐ Chī Miàn Bāo, Hē Niú Nǎi.", "Buổi sáng chúng tôi cùng ăn bánh mì và uống sữa."], [40.25, 42.702, "爸爸在家看书。", "Bà Ba Zài Jiā Kàn Shū.", "Bố ở nhà đọc sách."], [42.717, 45.145, "妈妈做中国菜。", "Mā Ma Zuò Zhōng Guó Cài.", "Mẹ nấu món Trung."], [45.15, 48.37, "我问妈妈：菜好吃吗？", "Wǒ Wèn Mā Ma: Cài Hǎo Chī Ma?", "Tôi hỏi mẹ: Món ăn có ngon không?"], [48.37, 51.302, "妈妈说：很好吃。", "Mā Ma Shuō: Hěn Hǎo Chī.", "Mẹ nói: Rất ngon."], [51.302, 54.21, "吃完饭，我看书。", "Chī Wán Fàn, Wǒ Kàn Shū.", "Ăn cơm xong, tôi đọc sách."], [54.217, 56.765, "我有一个字不知道。", "Wǒ Yǒu Yí Gè Zì Bù Zhī Dào.", "Tôi có một chữ không biết."], [56.783, 59.763, "姐姐帮助我写汉字。", "Jiě Jie Bāng Zhù Wǒ Xiě Hàn Zì.", "Chị giúp tôi viết chữ Hán."], [59.763, 63.679, "我说：谢谢姐姐，我很高兴。", "Wǒ Shuō: Xiè Xie Jiě Jie, Wǒ Hěn Gāo Xìng.", "Tôi nói: Cảm ơn chị, em rất vui."], [63.683, 66.039, "我很爱我的家。", "Wǒ Hěn Ài Wǒ De Jiā.", "Tôi rất yêu nhà mình."]]}, "hsk1-03": {"dur": 72.35, "cues": [[6.886, 9.526, "我的学校在北京。", "Wǒ De Xué Xiào Zài Běi Jīng.", "Trường của tôi ở Bắc Kinh."], [9.526, 12.626, "我每天早上七点起床。", "Wǒ Měi Tiān Zǎo Shàng Qī Diǎn Qǐ Chuáng.", "Mỗi sáng tôi dậy lúc bảy giờ."], [12.626, 16.036, "早上下雨了，我带雨伞。", "Zǎo Shàng Xià Yǔ Le, Wǒ Dài Yǔ Sǎn.", "Buổi sáng trời mưa, tôi mang theo ô."], [16.036, 19.544, "我吃一点儿饭，然后去学校。", "Wǒ Chī Yì Diǎn Ér Fàn, Rán Hòu Qù Xué Xiào.", "Tôi ăn một chút rồi đến trường."], [19.569, 22.739, "我坐公共汽车去学校。", "Wǒ Zuò Gōng Gòng Qì Chē Qù Xué Xiào.", "Tôi đi xe buýt đến trường."], [22.739, 25.647, "路上我看见一个同学。", "Lù Shang Wǒ Kàn Jiàn Yí Gè Tóng Xué.", "Trên đường tôi nhìn thấy một bạn học."], [25.672, 28.964, "同学问我：你今天好吗？", "Tóng Xué Wèn Wǒ: Nǐ Jīn Tiān Hǎo Ma?", "Bạn học hỏi tôi: Hôm nay bạn có khỏe không?"], [28.964, 32.184, "我说：我很好，谢谢。", "Wǒ Shuō: Wǒ Hěn Hǎo, Xiè Xie.", "Tôi nói: Tôi rất khỏe, cảm ơn bạn."], [32.206, 35.446, "学校门口有很多学生。", "Xué Xiào Mén Kǒu Yǒu Hěn Duō Xué Shēng.", "Cổng trường có rất nhiều học sinh."], [35.446, 38.306, "我跟同学说你好。", "Wǒ Gēn Tóng Xué Shuō Nǐ Hǎo.", "Tôi chào bạn học."], [38.306, 42.006, "同学也说你好，我们很高兴。", "Tóng Xué Yě Shuō Nǐ Hǎo, Wǒ Men Hěn Gāo Xìng.", "Bạn học cũng chào tôi, chúng tôi rất vui."], [42.012, 44.92, "中午我在学校吃饭。", "Zhōng Wǔ Wǒ Zài Xué Xiào Chī Fàn.", "Trưa tôi ăn cơm ở trường."], [44.92, 47.512, "中午的饭很好吃。", "Zhōng Wǔ De Fàn Hěn Hǎo Chī.", "Cơm trưa rất ngon."], [47.512, 50.228, "下午四点我回家。", "Xià Wǔ Sì Diǎn Wǒ Huí Jiā.", "Bốn giờ chiều tôi về nhà."], [50.246, 53.298, "下午我回家写汉字。", "Xià Wǔ Wǒ Huí Jiā Xiě Hàn Zì.", "Buổi chiều tôi về nhà viết chữ Hán."], [53.298, 55.774, "我写错了一个字。", "Wǒ Xiě Cuò Le Yí Gè Zì.", "Tôi viết sai một chữ."], [55.774, 62.162, "学校不大，可是老师和同学都很好，我喜欢我的学校。", "Xué Xiào Bú Dà, Kě Shì Lǎo Shī Hé Tóng Xué Dōu Hěn Hǎo, Wǒ Xǐ Huan Wǒ De Xué Xiào.", "Trường không lớn, nhưng thầy cô và các bạn đều rất tốt, tôi rất thích trường của mình."]]}, "hsk1-04": {"dur": 69.39, "cues": [[6.268, 9.488, "你们知道我中午吃什么吗？", "Nǐ Men Zhī Dào Wǒ Zhōng Wǔ Chī Shén Me Ma?", "Các bạn có biết trưa nay tôi ăn gì không?"], [9.488, 12.924, "今天中午我去饭馆吃饭。", "Jīn Tiān Zhōng Wǔ Wǒ Qù Fàn Guǎn Chī Fàn.", "Trưa nay tôi ra quán ăn cơm."], [12.935, 15.627, "饭馆离学校不远。", "Fàn Guǎn Lí Xué Xiào Bù Yuǎn.", "Quán ăn cách trường không xa."], [15.635, 18.135, "饭馆里人很多。", "Fàn Guǎn Lǐ Rén Hěn Duō.", "Trong quán có rất nhiều người."], [18.135, 20.275, "我坐在窗口。", "Wǒ Zuò Zài Chuāng Kǒu.", "Tôi ngồi cạnh cửa sổ."], [20.275, 23.399, "我想吃米饭和青菜。", "Wǒ Xiǎng Chī Mǐ Fàn Hé Qīng Cài.", "Tôi muốn ăn cơm và rau."], [23.408, 26.628, "服务员问我：你吃什么？", "Fú Wù Yuán Wèn Wǒ: Nǐ Chī Shén Me?", "Nhân viên hỏi tôi: Bạn ăn gì?"], [26.628, 30.348, "我说：我吃米饭和青菜。", "Wǒ Shuō: Wǒ Chī Mǐ Fàn Hé Qīng Cài.", "Tôi nói: Tôi ăn cơm và rau xanh."], [30.348, 33.544, "我喝一杯茶，茶不热。", "Wǒ Hē Yì Bēi Chá, Chá Bú Rè.", "Tôi uống một cốc trà, trà không nóng."], [33.548, 36.624, "我说：请给我热茶。", "Wǒ Shuō: Qǐng Gěi Wǒ Rè Chá.", "Tôi nói: Xin cho tôi trà nóng."], [36.624, 40.228, "服务员给我热茶，我说谢谢。", "Fú Wù Yuán Gěi Wǒ Rè Chá, Wǒ Shuō Xiè Xie.", "Nhân viên đưa cho tôi trà nóng, tôi nói cảm ơn."], [40.248, 43.444, "饭很好吃，我很高兴。", "Fàn Hěn Hǎo Chī, Wǒ Hěn Gāo Xìng.", "Cơm rất ngon, tôi rất vui."], [43.448, 46.476, "我问：一共多少钱？", "Wǒ Wèn: Yí Gòng Duō Shǎo Qián?", "Tôi hỏi: Tổng cộng bao nhiêu tiền?"], [46.476, 49.624, "服务员说：十块钱。", "Fú Wù Yuán Shuō: Shí Kuài Qián.", "Nhân viên nói: Mười đồng."], [49.628, 52.872, "吃完饭我给妈妈打电话。", "Chī Wán Fàn Wǒ Gěi Mā Ma Dǎ Diàn Huà.", "Ăn xong tôi gọi điện cho mẹ."], [52.872, 59.14, "我对妈妈说：今天的饭很好吃。妈妈笑了，我也笑了。", "Wǒ Duì Mā Ma Shuō: Jīn Tiān De Fàn Hěn Hǎo Chī. Mā Ma Xiào Le, Wǒ Yě Xiào Le.", "Tôi nói với mẹ: Cơm hôm nay rất ngon. Mẹ cười, tôi cũng cười."]]}, "hsk1-05": {"dur": 81.0, "cues": [[6.874, 9.566, "你们喜欢吃水果吗？", "Nǐ Men Xǐ Huan Chī Shuǐ Guǒ Ma?", "Các bạn có thích ăn hoa quả không?"], [9.566, 12.69, "妹妹说：我想吃水果。", "Mèi Mei Shuō: Wǒ Xiǎng Chī Shuǐ Guǒ.", "Em gái nói: Em muốn ăn hoa quả."], [12.707, 15.277, "我去商店买东西。", "Wǒ Qù Shāng Diàn Mǎi Dōng Xī.", "Tôi đi cửa hàng mua đồ."], [15.277, 18.737, "商店不大，可是东西很多。", "Shāng Diàn Bú Dà, Kě Shì Dōng Xī Hěn Duō.", "Cửa hàng không lớn nhưng đồ rất nhiều."], [18.744, 22.084, "我在商店看见好朋友大卫。", "Wǒ Zài Shāng Diàn Kàn Jiàn Hǎo Péng Yǒu Dà Wèi.", "Ở cửa hàng tôi nhìn thấy người bạn tốt Đại Vệ."], [22.084, 25.544, "我买六个苹果和三个香蕉。", "Wǒ Mǎi Liù Gè Píng Guǒ Hé Sān Gè Xiāng Jiāo.", "Tôi mua sáu quả táo và ba quả chuối."], [25.544, 29.22, "苹果不贵，香蕉也很便宜。", "Píng Guǒ Bú Guì, Xiāng Jiāo Yě Hěn Pián Yi.", "Táo không đắt, chuối cũng rất rẻ."], [29.224, 32.372, "苹果和香蕉都很好看。", "Píng Guǒ Hé Xiāng Jiāo Dōu Hěn Hǎo Kàn.", "Táo và chuối đều trông rất đẹp."], [32.39, 35.922, "我想买牛奶，可是没有牛奶。", "Wǒ Xiǎng Mǎi Niú Nǎi, Kě Shì Méi Yǒu Niú Nǎi.", "Tôi muốn mua sữa nhưng không có sữa."], [35.922, 38.446, "我还买了一瓶水。", "Wǒ Hái Mǎi Le Yì Píng Shuǐ.", "Tôi còn mua một chai nước."], [38.457, 41.173, "我问苹果多少钱。", "Wǒ Wèn Píng Guǒ Duō Shǎo Qián.", "Tôi hỏi táo bao nhiêu tiền."], [41.173, 43.865, "一个苹果两块钱。", "Yí Gè Píng Guǒ Liǎng Kuài Qián.", "Một quả táo hai đồng."], [43.865, 48.645, "三个香蕉三块钱，一瓶水五块钱。", "Sān Gè Xiāng Jiāo Sān Kuài Qián, Yì Píng Shuǐ Wǔ Kuài Qián.", "Ba quả chuối ba đồng, một chai nước năm đồng."], [48.657, 52.137, "服务员说：一共二十块钱。", "Fú Wù Yuán Shuō: Yí Gòng Èr Shí Kuài Qián.", "Nhân viên nói: Tổng cộng hai mươi đồng."], [52.137, 55.285, "我回家和家人一起吃。", "Wǒ Huí Jiā Hé Jiā Rén Yì Qǐ Chī.", "Tôi về nhà ăn cùng người trong nhà."], [55.304, 58.714, "妹妹看见水果，很高兴。", "Mèi Mei Kàn Jiàn Shuǐ Guǒ, Hěn Gāo Xìng.", "Em gái nhìn thấy hoa quả, rất vui."], [58.714, 61.714, "我和妹妹一起吃水果。", "Wǒ Hé Mèi Mei Yì Qǐ Chī Shuǐ Guǒ.", "Tôi và em gái cùng ăn hoa quả."], [61.714, 65.342, "妈妈也吃一个苹果，很好吃。", "Mā Ma Yě Chī Yí Gè Píng Guǒ, Hěn Hǎo Chī.", "Mẹ cũng ăn một quả táo, rất ngon."], [65.342, 70.794, "妹妹吃了一个香蕉，说：真好吃！我们都笑了。", "Mèi Mei Chī Le Yí Gè Xiāng Jiāo, Shuō: Zhēn Hǎo Chī! Wǒ Men Dōu Xiào Le.", "Em gái ăn một quả chuối rồi nói: Ngon thật! Cả nhà đều cười."]]}, "hsk1-06": {"dur": 69.78, "cues": [[7.22, 11.04, "今天是星期六，我不去学校。", "Jīn Tiān Shì Xīng Qī Liù, Wǒ Bú Qù Xué Xiào.", "Hôm nay là thứ Bảy, tôi không đến trường."], [11.04, 13.56, "今天天气很好。", "Jīn Tiān Tiān Qì Hěn Hǎo.", "Hôm nay thời tiết rất đẹp."], [13.56, 15.916, "不冷，也不热。", "Bù Lěng, Yě Bú Rè.", "Không lạnh, cũng không nóng."], [15.927, 18.955, "早上我给同学打电话。", "Zǎo Shàng Wǒ Gěi Tóng Xué Dǎ Diàn Huà.", "Buổi sáng tôi gọi điện cho bạn học."], [18.96, 21.82, "我和同学去公园。", "Wǒ Hé Tóng Xué Qù Gōng Yuán.", "Tôi và bạn học đi công viên."], [21.82, 24.728, "我在公园门口等他。", "Wǒ Zài Gōng Yuán Mén Kǒu Děng Tā.", "Tôi đợi bạn ấy ở cổng công viên."], [24.73, 27.83, "等了一会儿，同学来了。", "Děng Le Yí Huì Er, Tóng Xué Lái Le.", "Đợi một lát thì bạn học đến."], [27.83, 31.458, "同学说：今天天气真好。", "Tóng Xué Shuō: Jīn Tiān Tiān Qì Zhēn Hǎo.", "Bạn học nói: Hôm nay thời tiết thật đẹp."], [31.463, 35.091, "我们在公园坐一会儿，喝茶。", "Wǒ Men Zài Gōng Yuán Zuò Yí Huì Er, Hē Chá.", "Chúng tôi ngồi một lát ở công viên và uống trà."], [35.091, 38.815, "我们喝茶，说话，很高兴。", "Wǒ Men Hē Chá, Shuō Huà, Hěn Gāo Xìng.", "Chúng tôi uống trà, nói chuyện, rất vui."], [38.83, 41.282, "中午太阳很好。", "Zhōng Wǔ Tài Yáng Hěn Hǎo.", "Trưa nắng rất đẹp."], [41.297, 44.565, "我们在公园看见很多花。", "Wǒ Men Zài Gōng Yuán Kàn Jiàn Hěn Duō Huā.", "Chúng tôi thấy rất nhiều hoa ở công viên."], [44.565, 47.905, "我问同学：花好看吗？", "Wǒ Wèn Tóng Xué: Huā Hǎo Kàn Ma?", "Tôi hỏi bạn học: Hoa có đẹp không?"], [47.907, 51.103, "同学说：花很好看。", "Tóng Xué Shuō: Huā Hěn Hǎo Kàn.", "Bạn học nói: Hoa rất đẹp."], [51.107, 54.759, "我说：请给我拍照，好吗？", "Wǒ Shuō: Qǐng Gěi Wǒ Pāi Zhào, Hǎo Ma?", "Tôi nói: Chụp ảnh cho tôi nhé, được không?"], [54.759, 59.587, "朋友给我拍照，我们都笑了。今天真好。", "Péng Yǒu Gěi Wǒ Pāi Zhào, Wǒ Men Dōu Xiào Le. Jīn Tiān Zhēn Hǎo.", "Bạn chụp ảnh cho tôi, chúng tôi đều cười. Hôm nay thật tuyệt."]]}, "hsk1-07": {"dur": 67.44, "cues": [[6.771, 9.031, "你有好朋友吗？", "Nǐ Yǒu Hǎo Péng Yǒu Ma?", "Bạn có bạn tốt không?"], [9.031, 11.435, "我有一个好朋友。", "Wǒ Yǒu Yí Gè Hǎo Péng Yǒu.", "Tôi có một người bạn tốt."], [11.438, 14.826, "他叫大卫，今年十九岁。", "Tā Jiào Dà Wèi, Jīn Nián Shí Jiǔ Suì.", "Anh ấy tên David, năm nay mười chín tuổi."], [14.838, 18.418, "他是学生，也在北京学习。", "Tā Shì Xué Shēng, Yě Zài Běi Jīng Xué Xí.", "Anh ấy là học sinh và cũng học ở Bắc Kinh."], [18.418, 20.798, "我们在学校认识。", "Wǒ Men Zài Xué Xiào Rèn Shi.", "Chúng tôi quen nhau ở trường."], [20.798, 23.298, "我们常常一起看书。", "Wǒ Men Cháng Cháng Yì Qǐ Kàn Shū.", "Chúng tôi thường đọc sách cùng nhau."], [23.298, 26.83, "大卫说：我们一起学习吧。", "Dà Wèi Shuō: Wǒ Men Yì Qǐ Xué Xí Ba.", "David nói: Chúng ta cùng học nhé."], [26.831, 29.763, "大卫住在学校旁边。", "Dà Wèi Zhù Zài Xué Xiào Páng Biān.", "David sống cạnh trường."], [29.764, 32.168, "我常常去他家。", "Wǒ Cháng Cháng Qù Tā Jiā.", "Tôi thường đến nhà anh ấy."], [32.168, 34.788, "他会说一点儿汉语。", "Tā Huì Shuō Yì Diǎn Ér Hàn Yǔ.", "Anh ấy nói được một chút tiếng Trung."], [34.798, 37.634, "可是他写汉字不好。", "Kě Shì Tā Xiě Hàn Zì Bù Hǎo.", "Nhưng anh ấy viết chữ Hán không tốt."], [37.634, 40.134, "我教他写汉字。", "Wǒ Jiào Tā Xiě Hàn Zì.", "Tôi dạy anh ấy viết chữ Hán."], [40.138, 42.998, "他写错了，我帮他。", "Tā Xiě Cuò Le, Wǒ Bāng Tā.", "Anh ấy viết sai, tôi giúp anh ấy."], [43.004, 45.6, "他也教我说英语。", "Tā Yě Jiào Wǒ Shuō Yīng Yǔ.", "Anh ấy cũng dạy tôi nói tiếng Anh."], [45.6, 48.244, "我说英语也不好。", "Wǒ Shuō Yīng Yǔ Yě Bù Hǎo.", "Tôi nói tiếng Anh cũng không tốt."], [48.244, 51.44, "我们一起学习，很高兴。", "Wǒ Men Yì Qǐ Xué Xí, Hěn Gāo Xìng.", "Chúng tôi học cùng nhau, rất vui."], [51.444, 53.56, "我们是好朋友。", "Wǒ Men Shì Hǎo Péng Yǒu.", "Chúng tôi là bạn tốt."], [53.56, 57.26, "大卫说：有你这个朋友真好。", "Dà Wèi Shuō: Yǒu Nǐ Zhè Gè Péng Yǒu Zhēn Hǎo.", "Đại Vệ nói: Có người bạn như bạn thật tốt."]]}, "hsk1-08": {"dur": 66.41, "cues": [[6.711, 10.507, "早上，妈妈说：我不舒服。", "Zǎo Shang, Mā Ma Shuō: Wǒ Bù Shū Fú.", "Buổi sáng, mẹ nói: Mẹ không khỏe."], [10.507, 13.511, "今天妈妈不太舒服。", "Jīn Tiān Mā Ma Bú Tài Shū Fú.", "Hôm nay mẹ hơi không khỏe."], [13.511, 15.699, "妈妈说头痛。", "Mā Ma Shuō Tóu Tòng.", "Mẹ nói đau đầu."], [15.711, 17.563, "妈妈很累。", "Mā Ma Hěn Lèi.", "Mẹ rất mệt."], [17.563, 20.759, "爸爸说：我们去医院吧。", "Bà Ba Shuō: Wǒ Men Qù Yī Yuàn Ba.", "Bố nói: Chúng ta đi bệnh viện nhé."], [20.761, 24.001, "我和爸爸带妈妈去医院。", "Wǒ Hé Bà Ba Dài Mā Ma Qù Yī Yuàn.", "Tôi và bố đưa mẹ đến bệnh viện."], [24.001, 26.811, "我们坐公共汽车去。", "Wǒ Men Zuò Gōng Gòng Qì Chē Qù.", "Chúng tôi đi xe buýt đến đó."], [26.811, 29.211, "医院里人很多。", "Yī Yuàn Lǐ Rén Hěn Duō.", "Trong bệnh viện có rất nhiều người."], [29.211, 31.851, "妈妈坐在这里等。", "Mā Ma Zuò Zài Zhè Lǐ Děng.", "Mẹ ngồi ở đây đợi."], [31.851, 34.567, "我们等了二十分钟。", "Wǒ Men Děng Le Èr Shí Fēn Zhōng.", "Chúng tôi đợi hai mươi phút."], [34.584, 37.754, "医生问妈妈哪儿不舒服。", "Yī Shēng Wèn Mā Ma Nǎ Ér Bù Shū Fú.", "Bác sĩ hỏi mẹ chỗ nào không khỏe."], [37.754, 40.974, "医生说妈妈要多休息。", "Yī Shēng Shuō Mā Ma Yào Duō Xiū Xi.", "Bác sĩ nói mẹ cần nghỉ nhiều hơn."], [40.974, 44.386, "爸爸说：好的，谢谢。", "Bà Ba Shuō: Hǎo De, Xiè Xie.", "Bố nói: Vâng, cảm ơn bác sĩ."], [44.388, 46.72, "我给妈妈喝水。", "Wǒ Gěi Mā Ma Hē Shuǐ.", "Tôi cho mẹ uống nước."], [46.721, 50.373, "我说：妈妈，好好休息。", "Wǒ Shuō: Mā Ma, Hǎo Hǎo Xiū Xi.", "Tôi nói: Mẹ, mẹ nghỉ ngơi cho tốt nhé."], [50.373, 56.281, "妈妈睡了，我坐在她旁边。妈妈好多了，我笑了。", "Mā Ma Shuì Le, Wǒ Zuò Zài Tā Páng Biān. Mā Ma Hǎo Duō Le, Wǒ Xiào Le.", "Mẹ ngủ rồi, tôi ngồi bên cạnh mẹ. Mẹ đỡ nhiều rồi, tôi mỉm cười."]]}, "hsk1-09": {"dur": 62.56, "cues": [[7.531, 10.411, "今天上午我去学校。", "Jīn Tiān Shàng Wǔ Wǒ Qù Xué Xiào.", "Sáng nay tôi đến trường."], [10.411, 13.103, "现在是上午九点。", "Xiàn Zài Shì Shàng Wǔ Jiǔ Diǎn.", "Bây giờ là chín giờ sáng."], [13.103, 15.744, "我在教室里看书。", "Wǒ Zài Jiào Shì Lǐ Kàn Shū.", "Tôi đang đọc sách trong lớp."], [15.744, 18.292, "我们都在教室里。", "Wǒ Men Dōu Zài Jiào Shì Lǐ.", "Chúng tôi đều ở trong lớp học."], [18.311, 21.551, "同学说：老师马上来。", "Tóng Xué Shuō: Lǎo Shī Mǎ Shàng Lái.", "Bạn học nói: Thầy sắp đến rồi."], [21.551, 24.723, "九点十分，老师来了。", "Jiǔ Diǎn Shí Fēn, Lǎo Shī Lái Le.", "Chín giờ mười, thầy đến."], [24.723, 27.559, "老师说：你们好。", "Lǎo Shī Shuō: Nǐ Men Hǎo.", "Thầy nói: Chào các em."], [27.561, 30.441, "十点我们上汉语课。", "Shí Diǎn Wǒ Men Shàng Hàn Yǔ Kè.", "Mười giờ chúng tôi học tiếng Trung."], [30.441, 32.437, "我们打开书。", "Wǒ Men Dǎ Kāi Shū.", "Chúng tôi mở sách."], [32.437, 35.581, "老师说：请读课文。", "Lǎo Shī Shuō: Qǐng Dú Kè Wén.", "Thầy nói: Mời đọc bài."], [35.581, 38.129, "一些字我不知道。", "Yì Xiē Zì Wǒ Bù Zhī Dào.", "Một số chữ tôi không biết."], [38.129, 40.461, "我读得不太快。", "Wǒ Dú Dé Bú Tài Kuài.", "Tôi đọc không nhanh lắm."], [40.481, 42.693, "我读了三遍。", "Wǒ Dú Le Sān Biàn.", "Tôi đọc ba lần."], [42.693, 45.001, "我读得好多了。", "Wǒ Dú Dé Hǎo Duō Le.", "Tôi đọc tốt hơn nhiều rồi."], [45.014, 47.538, "老师说：很好。", "Lǎo Shī Shuō: Hěn Hǎo.", "Thầy nói: Rất tốt."], [47.538, 52.414, "我读了课文，笑了。我很喜欢学习汉语。", "Wǒ Dú Le Kè Wén, Xiào Le. Wǒ Hěn Xǐ Huan Xué Xí Hàn Yǔ.", "Tôi đọc xong bài khóa rồi mỉm cười. Tôi rất thích học tiếng Trung."]]}, "hsk1-10": {"dur": 67.38, "cues": [[7.174, 9.65, "今天是星期六。", "Jīn Tiān Shì Xīng Qī Liù.", "Hôm nay là thứ Bảy."], [9.674, 12.918, "我不上课，在家休息。", "Wǒ Bú Shàng Kè, Zài Jiā Xiū Xi.", "Tôi không đi học, nghỉ ở nhà."], [12.918, 16.426, "妈妈说：今天好好休息。", "Mā Ma Shuō: Jīn Tiān Hǎo Hǎo Xiū Xi.", "Mẹ nói: Hôm nay nghỉ ngơi cho tốt nhé."], [16.441, 19.301, "上午我起床很晚。", "Shàng Wǔ Wǒ Qǐ Chuáng Hěn Wǎn.", "Sáng tôi dậy rất muộn."], [19.301, 21.873, "我起床是十点。", "Wǒ Qǐ Chuáng Shì Shí Diǎn.", "Tôi dậy lúc mười giờ."], [21.874, 24.854, "我吃面包，喝牛奶。", "Wǒ Chī Miàn Bāo, Hē Niú Nǎi.", "Tôi ăn bánh mì và uống sữa."], [24.854, 27.834, "面包好吃，牛奶热。", "Miàn Bāo Hǎo Chī, Niú Nǎi Rè.", "Bánh mì ngon, sữa nóng."], [27.841, 31.997, "上午我看电视，下午我听音乐。", "Shàng Wǔ Wǒ Kàn Diàn Shì, Xià Wǔ Wǒ Tīng Yīn Yuè.", "Buổi sáng tôi xem ti vi, buổi chiều tôi nghe nhạc."], [32.007, 34.987, "下午我给朋友打电话。", "Xià Wǔ Wǒ Gěi Péng Yǒu Dǎ Diàn Huà.", "Chiều tôi gọi điện cho bạn."], [34.987, 38.951, "朋友说：你好，你有时间吗？", "Péng Yǒu Shuō: Nǐ Hǎo, Nǐ Yǒu Shí Jiān Ma?", "Bạn nói: Chào bạn, bạn có thời gian không?"], [38.951, 43.107, "我说：有，明天我们去商店吧。", "Wǒ Shuō: Yǒu, Míng Tiān Wǒ Men Qù Shāng Diàn Ba.", "Tôi nói: Có, ngày mai chúng ta đi cửa hàng nhé."], [43.121, 46.029, "晚上我们一家人吃饭。", "Wǎn Shàng Wǒ Men Yì Jiā Rén Chī Fàn.", "Buổi tối cả nhà tôi ăn cơm."], [46.029, 49.369, "爸爸说：中国菜好吃。", "Bà Ba Shuō: Zhōng Guó Cài Hǎo Chī.", "Bố nói: Món Trung Quốc ngon."], [49.369, 54.317, "我跟爸爸妈妈说：今天真好。我们都笑了。", "Wǒ Gēn Bà Ba Mā Ma Shuō: Jīn Tiān Zhēn Hǎo. Wǒ Men Dōu Xiào Le.", "Tôi nói với bố mẹ: Hôm nay thật tuyệt. Cả nhà đều cười."], [54.321, 57.109, "晚上我十点睡觉。", "Wǎn Shàng Wǒ Shí Diǎn Shuì Jiào.", "Tối tôi ngủ lúc mười giờ."]]}, "hsk1-11": {"dur": 66.19, "cues": [[6.674, 8.838, "你喜欢小猫吗？", "Nǐ Xǐ Huan Xiǎo Māo Ma?", "Bạn có thích mèo nhỏ không?"], [8.838, 11.338, "我家有一只小猫。", "Wǒ Jiā Yǒu Yì Zhī Xiǎo Māo.", "Nhà tôi có một con mèo nhỏ."], [11.341, 13.289, "它叫小白。", "Tā Jiào Xiǎo Bái.", "Nó tên là Tiểu Bạch."], [13.289, 16.461, "小猫很小，眼睛很大。", "Xiǎo Māo Hěn Xiǎo, Yǎn Jīng Hěn Dà.", "Mèo rất nhỏ, mắt rất to."], [16.474, 20.006, "它喜欢喝水，也喜欢睡觉。", "Tā Xǐ Huan Hē Shuǐ, Yě Xǐ Huan Shuì Jiào.", "Nó thích uống nước và cũng thích ngủ."], [20.007, 22.435, "它也喜欢吃鱼。", "Tā Yě Xǐ Huan Chī Yú.", "Nó cũng thích ăn cá."], [22.441, 25.253, "我每天都跟小猫玩儿。", "Wǒ Měi Tiān Dōu Gēn Xiǎo Māo Wán Ér.", "Mỗi ngày tôi đều chơi với mèo."], [25.253, 28.593, "我说：小白，来玩儿吧。", "Wǒ Shuō: Xiǎo Bái, Lái Wán Ér Ba.", "Tôi nói: Tiểu Bạch, đến chơi đi."], [28.607, 31.707, "小猫喜欢坐在我旁边。", "Xiǎo Māo Xǐ Huan Zuò Zài Wǒ Páng Biān.", "Mèo thích ngồi cạnh tôi."], [31.707, 33.747, "我给它喝水。", "Wǒ Gěi Tā Hē Shuǐ.", "Tôi cho nó uống nước."], [33.747, 36.487, "它看见小球就跑。", "Tā Kàn Jiàn Xiǎo Qiú Jiù Pǎo.", "Nó thấy quả bóng nhỏ là chạy."], [36.487, 40.019, "可是有一天，小球没有了。", "Kě Shì Yǒu Yì Tiān, Xiǎo Qiú Méi Yǒu Le.", "Nhưng có một ngày, quả bóng nhỏ không còn nữa."], [40.019, 42.183, "小猫不高兴。", "Xiǎo Māo Bù Gāo Xìng.", "Mèo không vui."], [42.187, 45.719, "我看见小球在桌子旁边。", "Wǒ Kàn Jiàn Xiǎo Qiú Zài Zhuō Zi Páng Biān.", "Tôi thấy quả bóng nhỏ ở cạnh bàn."], [45.719, 47.979, "小猫马上跑。", "Xiǎo Māo Mǎ Shàng Pǎo.", "Mèo lập tức chạy."], [47.987, 50.847, "妈妈说小猫很可爱。", "Mā Ma Shuō Xiǎo Māo Hěn Kě Ài.", "Mẹ nói mèo rất đáng yêu."], [50.847, 53.155, "我每天都高兴。", "Wǒ Měi Tiān Dōu Gāo Xìng.", "Mỗi ngày tôi đều vui."], [53.157, 55.967, "小白是我的好朋友。", "Xiǎo Bái Shì Wǒ De Hǎo Péng Yǒu.", "Tiểu Bạch là bạn tốt của tôi."]]}, "hsk1-12": {"dur": 77.36, "cues": [[7.224, 9.7, "今天是星期六。", "Jīn Tiān Shì Xīng Qī Liù.", "Hôm nay là thứ Bảy."], [9.724, 12.704, "下午我给朋友打电话。", "Xià Wǔ Wǒ Gěi Péng Yǒu Dǎ Diàn Huà.", "Buổi chiều tôi gọi điện cho bạn."], [12.704, 16.116, "我说：你现在有时间吗？", "Wǒ Shuō: Nǐ Xiàn Zài Yǒu Shí Jiān Ma?", "Tôi nói: Bây giờ bạn có thời gian không?"], [16.124, 19.968, "朋友说：有，我们去喝茶吧。", "Péng Yǒu Shuō: Yǒu, Wǒ Men Qù Hē Chá Ba.", "Bạn nói: Có, chúng ta đi uống trà nhé."], [19.968, 23.764, "我说：好，我们喝热茶。", "Wǒ Shuō: Hǎo, Wǒ Men Hē Rè Chá.", "Tôi nói: Được, chúng ta uống trà nóng."], [23.764, 27.104, "我们四点在学校门口见。", "Wǒ Men Sì Diǎn Zài Xué Xiào Mén Kǒu Jiàn.", "Chúng tôi gặp nhau lúc bốn giờ ở cổng trường."], [27.104, 30.252, "我坐公共汽车去学校。", "Wǒ Zuò Gōng Gòng Qì Chē Qù Xué Xiào.", "Tôi đi xe buýt đến trường."], [30.271, 33.899, "我三点五十到学校门口。", "Wǒ Sān Diǎn Wǔ Shí Dào Xué Xiào Mén Kǒu.", "Tôi đến cổng trường lúc ba giờ năm mươi."], [33.899, 36.567, "我在门口等朋友。", "Wǒ Zài Mén Kǒu Děng Péng Yǒu.", "Tôi đợi bạn ở cổng."], [36.571, 38.639, "朋友还没来。", "Péng Yǒu Hái Méi Lái.", "Bạn còn chưa đến."], [38.639, 41.907, "我在门口等了二十分钟。", "Wǒ Zài Mén Kǒu Děng Le Èr Shí Fēn Zhōng.", "Tôi đợi ở cổng hai mươi phút."], [41.911, 43.907, "天气很冷。", "Tiān Qì Hěn Lěng.", "Trời rất lạnh."], [43.907, 46.287, "我给他打电话。", "Wǒ Gěi Tā Dǎ Diàn Huà.", "Tôi gọi điện cho bạn."], [46.291, 49.175, "他说：我马上到。", "Tā Shuō: Wǒ Mǎ Shàng Dào.", "Bạn nói: Tôi đến ngay."], [49.175, 51.915, "一会儿，朋友来了。", "Yí Huì Er, Péng Yǒu Lái Le.", "Một lúc sau, bạn đến."], [51.915, 55.759, "朋友说：对不起，我来晚了。", "Péng Yǒu Shuō: Duì Bù Qǐ, Wǒ Lái Wǎn Le.", "Bạn nói: Xin lỗi, tôi đến muộn."], [55.791, 59.443, "我说：你好，我很高兴。", "Wǒ Shuō: Nǐ Hǎo, Wǒ Hěn Gāo Xìng.", "Tôi nói: Chào bạn, tôi rất vui."], [59.457, 62.893, "我们喝了茶，说了很多话。", "Wǒ Men Hē Le Chá, Shuō Le Hěn Duō Huà.", "Chúng tôi uống trà và nói rất nhiều."], [62.893, 67.169, "他笑了，我也笑了。我们是好朋友。", "Tā Xiào Le, Wǒ Yě Xiào Le. Wǒ Men Shì Hǎo Péng Yǒu.", "Bạn cười, tôi cũng cười. Chúng tôi là bạn tốt."]]}, "hsk1-13": {"dur": 65.48, "cues": [[6.887, 9.243, "今天有汉语课。", "Jīn Tiān Yǒu Hàn Yǔ Kè.", "Hôm nay có tiết tiếng Trung."], [9.243, 12.199, "我学习汉语十个月了。", "Wǒ Xué Xí Hàn Yǔ Shí Gè Yuè Le.", "Tôi học tiếng Trung được mười tháng."], [12.22, 14.888, "我觉得汉语很有用。", "Wǒ Jué De Hàn Yǔ Hěn Yǒu Yòng.", "Tôi thấy tiếng Trung rất hữu ích."], [14.888, 17.436, "我喜欢学习汉语。", "Wǒ Xǐ Huan Xué Xí Hàn Yǔ.", "Tôi thích học tiếng Trung."], [17.454, 20.986, "我能说一点儿，也能写一些字。", "Wǒ Néng Shuō Yì Diǎn Ér, Yě Néng Xiě Yì Xiē Zì.", "Tôi nói được một chút và cũng viết được một số chữ."], [20.987, 24.063, "同学问我：你能读吗？", "Tóng Xué Wèn Wǒ: Nǐ Néng Dú Ma?", "Bạn học hỏi tôi: Bạn đọc được không?"], [24.063, 26.967, "我说：我能读一点儿。", "Wǒ Shuō: Wǒ Néng Dú Yì Diǎn Ér.", "Tôi nói: Tôi đọc được một chút."], [26.967, 29.995, "老师说我的汉语很好。", "Lǎo Shī Shuō Wǒ De Hàn Yǔ Hěn Hǎo.", "Thầy nói tiếng Trung của tôi rất tốt."], [30.0, 33.412, "今天老师教我们五个汉字。", "Jīn Tiān Lǎo Shī Jiào Wǒ Men Wǔ Gè Hàn Zì.", "Hôm nay thầy dạy chúng tôi năm chữ Hán."], [33.412, 36.512, "老师写汉字，我们看。", "Lǎo Shī Xiě Hàn Zì, Wǒ Men Kàn.", "Thầy viết chữ Hán, chúng tôi nhìn theo."], [36.534, 39.586, "我在本子上写了三遍。", "Wǒ Zài Běn Zi Shàng Xiě Le Sān Biàn.", "Tôi viết ba lần vào vở."], [39.6, 42.316, "有一个字我写错了。", "Yǒu Yí Gè Zì Wǒ Xiě Cuò Le.", "Có một chữ tôi viết sai."], [42.316, 44.168, "我不高兴。", "Wǒ Bù Gāo Xìng.", "Tôi không vui."], [44.17, 46.238, "同学帮助我。", "Tóng Xué Bāng Zhù Wǒ.", "Bạn học giúp tôi."], [46.238, 48.834, "我说：谢谢你。", "Wǒ Shuō: Xiè Xiè Nǐ.", "Tôi nói: Cảm ơn bạn."], [48.837, 51.289, "现在我会写了。", "Xiàn Zài Wǒ Huì Xiě Le.", "Bây giờ tôi viết được rồi."], [51.289, 55.277, "同学说：你的字真好。我笑了。", "Tóng Xué Shuō: Nǐ De Zì Zhēn Hǎo. Wǒ Xiào Le.", "Bạn học nói: Chữ của bạn thật đẹp. Tôi mỉm cười."]]}, "hsk1-14": {"dur": 62.44, "cues": [[6.418, 8.894, "今天是星期六。", "Jīn Tiān Shì Xīng Qī Liù.", "Hôm nay là thứ Bảy."], [8.894, 11.85, "今天晚上我看电影。", "Jīn Tiān Wǎn Shàng Wǒ Kàn Diàn Yǐng.", "Tối nay tôi xem phim."], [11.851, 14.975, "我问同学：你们去吗？", "Wǒ Wèn Tóng Xué: Nǐ Men Qù Ma?", "Tôi hỏi các bạn học: Các bạn đi không?"], [14.975, 18.291, "他们说：好，我们去。", "Tā Men Shuō: Hǎo, Wǒ Men Qù.", "Họ nói: Được, chúng tôi đi."], [18.291, 21.319, "我和两个同学一起看。", "Wǒ Hé Liǎng Gè Tóng Xué Yì Qǐ Kàn.", "Tôi xem cùng hai bạn học."], [21.319, 24.107, "我们六点去电影院。", "Wǒ Men Liù Diǎn Qù Diàn Yǐng Yuàn.", "Chúng tôi đến rạp phim lúc sáu giờ."], [24.125, 27.105, "电影院离学校不远。", "Diàn Yǐng Yuàn Lí Xué Xiào Bù Yuǎn.", "Rạp phim không xa trường."], [27.105, 28.885, "票不贵。", "Piào Bú Guì.", "Vé không đắt."], [28.891, 31.415, "我们买了三张票。", "Wǒ Men Mǎi Le Sān Zhāng Piào.", "Chúng tôi mua ba vé."], [31.425, 34.573, "电影七点十分开始。", "Diàn Yǐng Qī Diǎn Shí Fēn Kāi Shǐ.", "Phim bắt đầu lúc bảy giờ mười."], [34.591, 37.667, "电影开始了，我们看。", "Diàn Yǐng Kāi Shǐ Le, Wǒ Men Kàn.", "Phim bắt đầu rồi, chúng tôi xem."], [37.691, 40.931, "看到一半，我们都笑了。", "Kàn Dào Yí Bàn, Wǒ Men Dōu Xiào Le.", "Xem được một nửa, chúng tôi đều cười."], [40.931, 44.411, "电影很好，我们都很高兴。", "Diàn Yǐng Hěn Hǎo, Wǒ Men Dōu Hěn Gāo Xìng.", "Phim rất hay, chúng tôi đều rất vui."], [44.411, 47.919, "看完以后我们坐车回家。", "Kàn Wán Yǐ Hòu Wǒ Men Zuò Chē Huí Jiā.", "Xem xong chúng tôi đi xe về nhà."], [47.919, 52.191, "路上，我们还说电影。我们都笑了。", "Lù Shang, Wǒ Men Hái Shuō Diàn Yǐng. Wǒ Men Dōu Xiào Le.", "Trên đường về, chúng tôi vẫn nói về bộ phim. Ai cũng cười."]]}, "hsk1-15": {"dur": 66.79, "cues": [[7.369, 10.037, "今天我要去北京。", "Jīn Tiān Wǒ Yào Qù Běi Jīng.", "Hôm nay tôi muốn đi Bắc Kinh."], [10.069, 12.761, "我下午去火车站。", "Wǒ Xià Wǔ Qù Huǒ Chē Zhàn.", "Buổi chiều tôi đi ga tàu."], [12.761, 15.141, "我的箱子很大。", "Wǒ De Xiāng Zǐ Hěn Dà.", "Vali của tôi rất to."], [15.169, 17.693, "火车站不太远。", "Huǒ Chē Zhàn Bú Tài Yuǎn.", "Ga tàu không quá xa."], [17.693, 21.609, "我有一个大箱子，所以坐出租车。", "Wǒ Yǒu Yí Gè Dà Xiāng Zǐ, Suǒ Yǐ Zuò Chū Zū Chē.", "Tôi có một vali lớn nên đi taxi."], [21.609, 24.637, "我说：请去火车站。", "Wǒ Shuō: Qǐng Qù Huǒ Chē Zhàn.", "Tôi nói: Xin cho đến ga tàu."], [24.637, 27.473, "出租车司机人很好。", "Chū Zū Chē Sī Jī Rén Hěn Hǎo.", "Tài xế taxi rất tốt."], [27.476, 30.116, "司机帮我拿箱子。", "Sī Jī Bāng Wǒ Ná Xiāng Zǐ.", "Tài xế giúp tôi cầm vali."], [30.116, 32.784, "我两点到火车站。", "Wǒ Liǎng Diǎn Dào Huǒ Chē Zhàn.", "Tôi đến ga lúc hai giờ."], [32.784, 35.428, "火车站里人很多。", "Huǒ Chē Zhàn Lǐ Rén Hěn Duō.", "Trong ga có rất nhiều người."], [35.449, 38.259, "我不知道火车在哪儿。", "Wǒ Bù Zhī Dào Huǒ Chē Zài Nǎ Ér.", "Tôi không biết tàu ở đâu."], [38.259, 41.527, "我问工作人员火车在哪儿。", "Wǒ Wèn Gōng Zuò Rén Yuán Huǒ Chē Zài Nǎ Ér.", "Tôi hỏi nhân viên tàu ở đâu."], [41.527, 43.883, "他说在三号。", "Tā Shuō Zài Sān Hào.", "Ông nói ở số ba."], [43.892, 46.392, "他说：跟我来。", "Tā Shuō: Gēn Wǒ Lái.", "Ông nói: Đi theo tôi."], [46.392, 49.78, "我谢谢他，然后去坐车。", "Wǒ Xiè Xiè Tā, Rán Hòu Qù Zuò Chē.", "Tôi cảm ơn ông rồi đi lên tàu."], [49.78, 53.288, "我在火车上喝水，看书。", "Wǒ Zài Huǒ Chē Shàng Hē Shuǐ, Kàn Shū.", "Trên tàu, tôi uống nước và đọc sách."], [53.288, 56.556, "北京，我来了。我笑了。", "Běi Jīng, Wǒ Lái Le. Wǒ Xiào Le.", "Bắc Kinh ơi, tôi đến đây. Tôi mỉm cười."]]}, "hsk1-16": {"dur": 68.13, "cues": [[7.122, 9.646, "今天天气很好。", "Jīn Tiān Tiān Qì Hěn Hǎo.", "Hôm nay thời tiết rất đẹp."], [9.655, 12.803, "今天我去商店买衣服。", "Jīn Tiān Wǒ Qù Shāng Diàn Mǎi Yī Fu.", "Hôm nay tôi đi cửa hàng mua quần áo."], [12.803, 15.519, "商店里衣服很多。", "Shāng Diàn Lǐ Yī Fu Hěn Duō.", "Trong cửa hàng có rất nhiều quần áo."], [15.522, 19.102, "售货员问我：你想买什么？", "Shòu Huò Yuán Wèn Wǒ: Nǐ Xiǎng Mǎi Shén Me?", "Nhân viên bán hàng hỏi tôi: Bạn muốn mua gì?"], [19.102, 22.154, "我说：我想买衣服。", "Wǒ Shuō: Wǒ Xiǎng Mǎi Yī Fu.", "Tôi nói: Tôi muốn mua quần áo."], [22.155, 25.395, "这件太大，那件太小。", "Zhè Jiàn Tài Dà, Nà Jiàn Tài Xiǎo.", "Cái này quá rộng, cái kia quá nhỏ."], [25.395, 28.351, "我说：有白色的吗？", "Wǒ Shuō: Yǒu Bái Sè De Ma?", "Tôi nói: Có cái màu trắng không?"], [28.351, 31.667, "那件白色的衣服很好看。", "Nà Jiàn Bái Sè De Yī Fu Hěn Hǎo Kàn.", "Cái áo màu trắng kia rất đẹp."], [31.695, 34.891, "售货员说这件很新。", "Shòu Huò Yuán Shuō Zhè Jiàn Hěn Xīn.", "Nhân viên nói cái này rất mới."], [34.895, 38.163, "我试了试，大小正好。", "Wǒ Shì Le Shì, Dà Xiǎo Zhèng Hǎo.", "Tôi thử, vừa người."], [38.195, 40.835, "我问：多少钱？", "Wǒ Wèn: Duō Shǎo Qián?", "Tôi hỏi: Bao nhiêu tiền?"], [40.835, 43.503, "我不想买太贵的。", "Wǒ Bù Xiǎng Mǎi Tài Guì De.", "Tôi không muốn mua cái quá đắt."], [43.535, 45.795, "八十块不贵。", "Bā Shí Kuài Bú Guì.", "Tám mươi đồng không đắt."], [45.802, 49.282, "我买了那件，花了八十块。", "Wǒ Mǎi Le Nà Jiàn, Huā Le Bā Shí Kuài.", "Tôi mua cái đó, hết tám mươi đồng."], [49.282, 52.31, "我很喜欢这件白衣服。", "Wǒ Hěn Xǐ Huan Zhè Jiàn Bái Yī Fu.", "Tôi rất thích cái áo trắng này."], [52.315, 55.055, "我穿新衣服回家。", "Wǒ Chuān Xīn Yī Fu Huí Jiā.", "Tôi mặc áo mới về nhà."], [55.055, 57.915, "妈妈说：很好看。", "Mā Ma Shuō: Hěn Hǎo Kàn.", "Mẹ nói: Rất đẹp."]]}, "hsk1-17": {"dur": 69.73, "cues": [[7.513, 10.973, "妈妈说：今天是你的生日。", "Mā Ma Shuō: Jīn Tiān Shì Nǐ De Shēng Rì.", "Mẹ nói: Hôm nay là sinh nhật của con."], [10.98, 13.576, "今天是我的生日。", "Jīn Tiān Shì Wǒ De Shēng Rì.", "Hôm nay là sinh nhật của tôi."], [13.576, 15.716, "我二十岁了。", "Wǒ Èr Shí Suì Le.", "Tôi đã hai mươi tuổi."], [15.72, 18.58, "早上妈妈做了面条。", "Zǎo Shàng Mā Ma Zuò Le Miàn Tiáo.", "Sáng mẹ nấu mì."], [18.58, 20.696, "面条很好吃。", "Miàn Tiáo Hěn Hǎo Chī.", "Mì rất ngon."], [20.7, 23.296, "我打电话给朋友。", "Wǒ Dǎ Diàn Huà Gěi Péng Yǒu.", "Tôi gọi điện cho bạn bè."], [23.296, 26.516, "我说：请来我家吃饭。", "Wǒ Shuō: Qǐng Lái Wǒ Jiā Chī Fàn.", "Tôi nói: Mời đến nhà tôi ăn cơm."], [26.533, 29.993, "朋友来我家，我们一起吃饭。", "Péng Yǒu Lái Wǒ Jiā, Wǒ Men Yì Qǐ Chī Fàn.", "Bạn đến nhà tôi, chúng tôi ăn cơm cùng nhau."], [29.993, 32.829, "我们吃面条和鸡蛋。", "Wǒ Men Chī Miàn Tiáo Hé Jī Dàn.", "Chúng tôi ăn mì và trứng."], [32.833, 36.485, "他们说生日快乐，我很高兴。", "Tā Men Shuō Shēng Rì Kuài Lè, Wǒ Hěn Gāo Xìng.", "Họ nói chúc mừng sinh nhật, tôi rất vui."], [36.5, 39.048, "朋友送我一本书。", "Péng Yǒu Sòng Wǒ Yì Běn Shū.", "Bạn tặng tôi một cuốn sách."], [39.066, 41.158, "我打开书看。", "Wǒ Dǎ Kāi Shū Kàn.", "Tôi mở sách ra xem."], [41.158, 43.898, "书的名字是《汉语》。", "Shū De Míng Zì Shì 《 Hàn Yǔ 》.", "Tên sách là Hán ngữ."], [43.9, 46.496, "我很喜欢这本书。", "Wǒ Hěn Xǐ Huan Zhè Běn Shū.", "Tôi rất thích cuốn sách này."], [46.5, 48.712, "我说谢谢你们。", "Wǒ Shuō Xiè Xiè Nǐ Men.", "Tôi nói cảm ơn mọi người."], [48.712, 51.548, "他们说：不客气。", "Tā Men Shuō: Bú Kè Qi.", "Họ nói: Không có gì."], [51.548, 56.64, "妈妈和朋友一起说：生日快乐！我们都笑了。", "Mā Ma Hé Péng Yǒu Yì Qǐ Shuō: Shēng Rì Kuài Lè! Wǒ Men Dōu Xiào Le.", "Mẹ và bạn bè cùng nói: Chúc mừng sinh nhật! Tất cả đều cười."], [56.64, 59.572, "我爱我的家人和朋友。", "Wǒ Ài Wǒ De Jiā Rén Hé Péng Yǒu.", "Tôi yêu gia đình và bạn bè của tôi."]]}, "hsk1-18": {"dur": 62.14, "cues": [[6.719, 9.555, "今天我想去公园。", "Jīn Tiān Wǒ Xiǎng Qù Gōng Yuán.", "Hôm nay tôi muốn đi công viên."], [9.555, 11.743, "今天下雨了。", "Jīn Tiān Xià Yǔ Le.", "Hôm nay trời mưa."], [11.752, 14.54, "雨是上午开始的。", "Yǔ Shì Shàng Wǔ Kāi Shǐ De.", "Mưa bắt đầu từ buổi sáng."], [14.552, 17.748, "雨很大，我不去公园。", "Yǔ Hěn Dà, Wǒ Bú Qù Gōng Yuán.", "Mưa rất to, tôi không đi công viên."], [17.748, 19.576, "我不高兴。", "Wǒ Bù Gāo Xìng.", "Tôi không vui."], [19.586, 22.878, "妈妈说：在家看书吧。", "Mā Ma Shuō: Zài Jiā Kàn Shū Ba.", "Mẹ nói: Ở nhà đọc sách đi."], [22.886, 26.178, "我在家看书，也喝茶。", "Wǒ Zài Jiā Kàn Shū, Yě Hē Chá.", "Tôi ở nhà đọc sách và uống trà."], [26.178, 28.342, "妈妈给我茶。", "Mā Ma Gěi Wǒ Chá.", "Mẹ đưa trà cho tôi."], [28.352, 30.684, "我在门口看雨。", "Wǒ Zài Mén Kǒu Kàn Yǔ.", "Tôi ở cửa nhìn mưa."], [30.686, 33.738, "我看见很多人有雨伞。", "Wǒ Kàn Jiàn Hěn Duō Rén Yǒu Yǔ Sǎn.", "Tôi thấy rất nhiều người có ô."], [33.752, 36.708, "一个朋友打电话给我。", "Yí Gè Péng Yǒu Dǎ Diàn Huà Gěi Wǒ.", "Một người bạn gọi điện cho tôi."], [36.708, 40.024, "他说：明天去公园吧。", "Tā Shuō: Míng Tiān Qù Gōng Yuán Ba.", "Anh ấy nói: Ngày mai đi công viên nhé."], [40.052, 42.48, "我在家听音乐。", "Wǒ Zài Jiā Tīng Yīn Yuè.", "Tôi ở nhà nghe nhạc."], [42.486, 44.698, "下午雨小了。", "Xià Wǔ Yǔ Xiǎo Le.", "Chiều mưa nhỏ đi."], [44.698, 47.006, "我看见太阳了。", "Wǒ Kàn Jiàn Tài Yáng Le.", "Tôi nhìn thấy mặt trời rồi."], [47.006, 51.926, "我看见太阳，妈妈也看见了。我们都笑了。", "Wǒ Kàn Jiàn Tài Yáng, Mā Ma Yě Kàn Jiàn Le. Wǒ Men Dōu Xiào Le.", "Tôi nhìn thấy mặt trời, mẹ cũng nhìn thấy. Cả hai mẹ con đều cười."]]}, "hsk1-19": {"dur": 62.34, "cues": [[6.401, 9.501, "我今天下午有汉语课。", "Wǒ Jīn Tiān Xià Wǔ Yǒu Hàn Yǔ Kè.", "Chiều nay tôi có tiết tiếng Trung."], [9.501, 13.081, "下午五点，汉语课结束了。", "Xià Wǔ Wǔ Diǎn, Hàn Yǔ Kè Jié Shù Le.", "Năm giờ chiều, tiết tiếng Trung kết thúc."], [13.101, 15.577, "同学也回家了。", "Tóng Xué Yě Huí Jiā Le.", "Bạn học cũng về nhà rồi."], [15.601, 18.293, "我跟老师说再见。", "Wǒ Gēn Lǎo Shī Shuō Zài Jiàn.", "Tôi chào tạm biệt thầy."], [18.293, 21.153, "老师说：明天见。", "Lǎo Shī Shuō: Míng Tiān Jiàn.", "Thầy nói: Ngày mai gặp lại."], [21.168, 23.044, "我去车站。", "Wǒ Qù Chē Zhàn.", "Tôi đi ra trạm xe."], [23.068, 25.544, "我在车站等车。", "Wǒ Zài Chē Zhàn Děng Chē.", "Tôi đợi xe ở trạm."], [25.544, 27.684, "车站人很多。", "Chē Zhàn Rén Hěn Duō.", "Trạm xe có nhiều người."], [27.701, 30.681, "等了一会儿，车没有来。", "Děng Le Yí Huì Er, Chē Méi Yǒu Lái.", "Đợi một lát, xe vẫn chưa đến."], [30.681, 33.397, "车来了，我上车。", "Chē Lái Le, Wǒ Shàng Chē.", "Xe đến, tôi lên xe."], [33.414, 36.322, "路上我给妈妈打电话。", "Lù Shang Wǒ Gěi Mā Ma Dǎ Diàn Huà.", "Trên đường tôi gọi điện cho mẹ."], [36.322, 38.99, "我说我六点回家。", "Wǒ Shuō Wǒ Liù Diǎn Huí Jiā.", "Tôi nói sáu giờ tôi về nhà."], [38.994, 42.67, "妈妈说：好，我在家等你。", "Mā Ma Shuō: Hǎo, Wǒ Zài Jiā Děng Nǐ.", "Mẹ nói: Được, mẹ ở nhà đợi con."], [42.67, 45.77, "妈妈说好，晚饭等我。", "Mā Ma Shuō Hǎo, Wǎn Fàn Děng Wǒ.", "Mẹ nói được, cơm tối đợi tôi."], [45.774, 48.49, "六点，我回家了。", "Liù Diǎn, Wǒ Huí Jiā Le.", "Sáu giờ, tôi về đến nhà."], [48.49, 52.046, "我们一起吃晚饭，我很高兴。", "Wǒ Men Yì Qǐ Chī Wǎn Fàn, Wǒ Hěn Gāo Xìng.", "Chúng tôi cùng ăn cơm tối, tôi rất vui."]]}, "hsk1-20": {"dur": 68.27, "cues": [[7.833, 10.765, "今天我认识一个朋友。", "Jīn Tiān Wǒ Rèn Shi Yí Gè Péng Yǒu.", "Hôm nay tôi quen một người bạn."], [10.766, 13.554, "你好，我叫安娜。", "Nǐ Hǎo, Wǒ Jiào Ān Nà.", "Xin chào, tôi tên là Anna."], [13.554, 17.566, "我是英国人，现在在中国工作。", "Wǒ Shì Yīng Guó Rén, Xiàn Zài Zài Zhōng Guó Gōng Zuò.", "Tôi là người Anh, hiện đang làm việc ở Trung Quốc."], [17.566, 21.53, "我的工作很忙，可是我喜欢这里。", "Wǒ De Gōng Zuò Hěn Máng, Kě Shì Wǒ Xǐ Huan Zhè Lǐ.", "Công việc của tôi rất bận, nhưng tôi thích nơi này."], [21.533, 25.065, "我问她：你也学习汉语吗？", "Wǒ Wèn Tā: Nǐ Yě Xué Xí Hàn Yǔ Ma?", "Tôi hỏi cô ấy: Bạn cũng học tiếng Trung à?"], [25.065, 29.485, "她说：我学习汉语，我的汉语不好。", "Tā Shuō: Wǒ Xué Xí Hàn Yǔ, Wǒ De Hàn Yǔ Bù Hǎo.", "Cô ấy nói: Tôi học tiếng Trung, tiếng Trung của tôi chưa tốt."], [29.499, 32.815, "认识你很高兴。谢谢你。", "Rèn Shi Nǐ Hěn Gāo Xìng. Xiè Xiè Nǐ.", "Rất vui được gặp bạn. Cảm ơn bạn."], [32.833, 35.813, "安娜在一家公司工作。", "Ān Nà Zài Yì Jiā Gōng Sī Gōng Zuò.", "Anna làm việc ở một công ty."], [35.813, 39.129, "她每天下午六点回家。", "Tā Měi Tiān Xià Wǔ Liù Diǎn Huí Jiā.", "Mỗi ngày sáu giờ chiều cô ấy về nhà."], [39.133, 41.773, "她回家吃晚饭。", "Tā Huí Jiā Chī Wǎn Fàn.", "Cô ấy về nhà ăn cơm tối."], [41.773, 44.465, "她也在学习汉语。", "Tā Yě Zài Xué Xí Hàn Yǔ.", "Cô ấy cũng đang học tiếng Trung."], [44.473, 47.309, "下午她请我喝茶。", "Xià Wǔ Tā Qǐng Wǒ Hē Chá.", "Buổi chiều cô ấy mời tôi uống trà."], [47.309, 49.929, "我们常常一起说话。", "Wǒ Men Cháng Cháng Yì Qǐ Shuō Huà.", "Chúng tôi thường nói chuyện cùng nhau."], [49.939, 53.207, "我们一起喝茶，很高兴。", "Wǒ Men Yì Qǐ Hē Chá, Hěn Gāo Xìng.", "Chúng tôi cùng uống trà, rất vui."], [53.207, 58.035, "安娜说：你是我在中国的好朋友。我笑了。", "Ān Nà Shuō: Nǐ Shì Wǒ Zài Zhōng Guó De Hǎo Péng Yǒu. Wǒ Xiào Le.", "Anna nói: Bạn là người bạn tốt của tôi ở Trung Quốc. Tôi mỉm cười."]]}, "hsk1-21": {"dur": 69.18, "cues": [[6.55, 9.098, "我喜欢我的朋友。", "Wǒ Xǐ Huan Wǒ De Péng Yǒu.", "Tôi quý người bạn của tôi."], [9.098, 12.726, "我有一个同学，也是我的朋友。", "Wǒ Yǒu Yí Gè Tóng Xué, Yě Shì Wǒ De Péng Yǒu.", "Tôi có một bạn học, cũng là bạn thân của tôi."], [12.73, 16.142, "他叫王华，今年十八岁。", "Tā Jiào Wáng Huá, Jīn Nián Shí Bā Suì.", "Anh ấy tên Vương Hoa, năm nay mười tám tuổi."], [16.142, 19.362, "我们每天一起上汉语课。", "Wǒ Men Měi Tiān Yì Qǐ Shàng Hàn Yǔ Kè.", "Mỗi ngày chúng tôi cùng học tiết tiếng Trung."], [19.363, 22.079, "他住在学校旁边。", "Tā Zhù Zài Xué Xiào Páng Biān.", "Anh ấy sống bên cạnh trường."], [22.079, 24.627, "学校离他家不远。", "Xué Xiào Lí Tā Jiā Bù Yuǎn.", "Trường không xa nhà anh ấy."], [24.63, 27.73, "星期六他去我家吃饭。", "Xīng Qī Liù Tā Qù Wǒ Jiā Chī Fàn.", "Thứ Bảy anh ấy đến nhà tôi ăn cơm."], [27.73, 30.686, "妈妈做了米饭和鸡蛋。", "Mā Ma Zuò Le Mǐ Fàn Hé Jī Dàn.", "Mẹ nấu cơm và trứng."], [30.697, 34.085, "妈妈问王华：饭好吃吗？", "Mā Ma Wèn Wáng Huá: Fàn Hǎo Chī Ma?", "Mẹ hỏi Vương Hoa: Cơm có ngon không?"], [34.085, 37.809, "王华说：很好吃，谢谢你。", "Wáng Huá Shuō: Hěn Hǎo Chī, Xiè Xiè Nǐ.", "Vương Hoa nói: Rất ngon, cảm ơn bạn."], [37.83, 41.338, "我们很高兴，也说很多话。", "Wǒ Men Hěn Gāo Xìng, Yě Shuō Hěn Duō Huà.", "Chúng tôi rất vui và cũng nói chuyện nhiều."], [41.363, 43.599, "妈妈也很高兴。", "Mā Ma Yě Hěn Gāo Xìng.", "Mẹ cũng rất vui."], [43.603, 47.207, "吃完饭，我有一个字写得不好。", "Chī Wán Fàn, Wǒ Yǒu Yí Gè Zì Xiě De Bù Hǎo.", "Ăn cơm xong, có một chữ tôi viết chưa tốt."], [47.207, 49.803, "他还帮我写汉字。", "Tā Hái Bāng Wǒ Xiě Hàn Zì.", "Anh ấy còn giúp tôi viết chữ Hán."], [49.803, 52.255, "现在我会写了。", "Xiàn Zài Wǒ Huì Xiě Le.", "Bây giờ tôi biết viết rồi."], [52.27, 55.658, "有这样的朋友，我很高兴。", "Yǒu Zhè Yàng De Péng Yǒu, Wǒ Hěn Gāo Xìng.", "Có người bạn như vậy, tôi rất vui."], [55.658, 58.97, "明天我们还一起上汉语课。", "Míng Tiān Wǒ Men Hái Yì Qǐ Shàng Hàn Yǔ Kè.", "Ngày mai chúng tôi lại cùng học tiết tiếng Trung."]]}, "hsk1-22": {"dur": 69.34, "cues": [[7.644, 10.168, "早上太阳很好。", "Zǎo Shang Tài Yáng Hěn Hǎo.", "Buổi sáng nắng đẹp."], [10.168, 14.177, "今天天气很好，我真的很高兴。", "Jīn Tiān Tiān Qì Hěn Hǎo, Wǒ Zhēn De Hěn Gāo Xìng.", "Hôm nay thời tiết rất đẹp, tôi thật sự rất vui."], [14.177, 17.396, "早上我不穿太多衣服。", "Zǎo Shang Wǒ Bù Chuān Tài Duō Yī Fu.", "Sáng tôi không mặc quá nhiều áo."], [17.41, 19.934, "同学问我去哪儿。", "Tóng Xué Wèn Wǒ Qù Nǎ Er.", "Bạn học hỏi tôi đi đâu."], [19.934, 22.723, "我说去公园看书。", "Wǒ Shuō Qù Gōng Yuán Kàn Shū.", "Tôi nói đi công viên đọc sách."], [22.744, 26.012, "同学说：我也去公园。", "Tóng Xué Shuō: Wǒ Yě Qù Gōng Yuán.", "Bạn học nói: Tôi cũng đi công viên."], [26.012, 28.483, "我们一起去公园。", "Wǒ Men Yì Qǐ Qù Gōng Yuán.", "Chúng tôi cùng đi công viên."], [28.483, 31.416, "公园里有很多的人。", "Gōng Yuán Lǐ Yǒu Hěn Duō De Rén.", "Trong công viên có rất nhiều người."], [31.416, 34.612, "我坐在桌子旁边看书。", "Wǒ Zuò Zài Zhuō Zi Páng Biān Kàn Shū.", "Tôi ngồi bên bàn đọc sách."], [34.617, 37.572, "中午朋友带苹果来。", "Zhōng Wǔ Péng Yǒu Dài Píng Guǒ Lái.", "Trưa bạn mang táo đến."], [37.572, 40.577, "朋友问：书好看吗？", "Péng Yǒu Wèn: Shū Hǎo Kàn Ma?", "Bạn hỏi: Sách có hay không?"], [40.584, 43.563, "我说：书很好看。", "Wǒ Shuō: Shū Hěn Hǎo Kàn.", "Tôi nói: Sách rất hay."], [43.563, 46.016, "我们一起吃苹果。", "Wǒ Men Yì Qǐ Chī Píng Guǒ.", "Chúng tôi cùng ăn táo."], [46.016, 48.324, "苹果很好吃。", "Píng Guǒ Hěn Hǎo Chī.", "Táo rất ngon."], [48.331, 51.931, "下午回家，妈妈也高兴了。", "Xià Wǔ Huí Jiā, Mā Ma Yě Gāo Xìng Le.", "Chiều về nhà, mẹ cũng vui."], [51.931, 54.886, "晚上我们一起吃晚饭。", "Wǎn Shang Wǒ Men Yì Qǐ Chī Wǎn Fàn.", "Buổi tối chúng tôi cùng ăn cơm tối."], [54.886, 59.139, "妈妈做的晚饭很好吃，我们都笑了。", "Mā Ma Zuò De Wǎn Fàn Hěn Hǎo Chī, Wǒ Men Dōu Xiào Le.", "Cơm tối mẹ nấu rất ngon, cả nhà đều cười."]]}, "hsk1-23": {"dur": 67.84, "cues": [[7.535, 9.723, "你喜欢喝茶吗？", "Nǐ Xǐ Huan Hē Chá Ma?", "Bạn có thích uống trà không?"], [9.723, 13.255, "我喜欢喝茶，每天都喝茶。", "Wǒ Xǐ Huan Hē Chá, Měi Tiān Dōu Hē Chá.", "Tôi thích uống trà, mỗi ngày đều uống trà."], [13.269, 16.129, "早上我喝一杯热茶。", "Zǎo Shang Wǒ Hē Yì Bēi Rè Chá.", "Sáng tôi uống một cốc trà nóng."], [16.129, 19.249, "茶太热了，等了一会儿。", "Chá Tài Rè Le, Děng Le Yí Huì Er.", "Trà nóng quá, tôi đợi một lát."], [19.249, 22.157, "热茶很好，也不贵。", "Rè Chá Hěn Hǎo, Yě Bù Guì.", "Trà nóng rất ngon và cũng không đắt."], [22.182, 24.582, "妈妈也喜欢喝茶。", "Mā Ma Yě Xǐ Huan Hē Chá.", "Mẹ cũng thích uống trà."], [24.582, 27.49, "下午我请朋友喝茶。", "Xià Wǔ Wǒ Qǐng Péng Yǒu Hē Chá.", "Chiều tôi mời bạn uống trà."], [27.49, 31.022, "朋友说：好，我下午来。", "Péng Yǒu Shuō: Hǎo, Wǒ Xià Wǔ Lái.", "Bạn nói: Được, chiều tôi đến."], [31.022, 34.098, "朋友说他也很喜欢茶。", "Péng Yǒu Shuō Tā Yě Hěn Xǐ Huan Chá.", "Bạn nói anh ấy cũng rất thích trà."], [34.098, 37.27, "我们坐在桌子旁边喝茶。", "Wǒ Men Zuò Zài Zhuō Zi Páng Biān Hē Chá.", "Chúng tôi ngồi bên bàn uống trà."], [37.272, 40.18, "我问朋友：茶好吗？", "Wǒ Wèn Péng Yǒu: Chá Hǎo Ma?", "Tôi hỏi bạn: Trà có ngon không?"], [40.18, 43.852, "朋友说：茶很好，谢谢你。", "Péng Yǒu Shuō: Chá Hěn Hǎo, Xiè Xiè Nǐ.", "Bạn nói: Trà rất ngon, cảm ơn bạn."], [43.852, 46.448, "还吃了一点儿米饭。", "Hái Chī Le Yì Diǎn Er Mǐ Fàn.", "Còn ăn một chút cơm."], [46.452, 49.504, "妈妈看见我们，笑了。", "Mā Ma Kàn Jiàn Wǒ Men, Xiào Le.", "Mẹ nhìn thấy chúng tôi và cười."], [49.519, 53.027, "晚上我不喝咖啡，我喝茶。", "Wǎn Shàng Wǒ Bù Hē Kā Fēi, Wǒ Hē Chá.", "Tối tôi không uống cà phê, tôi uống trà."], [53.027, 57.639, "妈妈喝了茶，说：茶真好。我笑了。", "Mā Ma Hē Le Chá, Shuō: Chá Zhēn Hǎo. Wǒ Xiào Le.", "Mẹ uống trà rồi nói: Trà thật ngon. Tôi mỉm cười."]]}, "hsk1-24": {"dur": 78.69, "cues": [[7.436, 10.392, "今天下午我有时间。", "Jīn Tiān Xià Wǔ Wǒ Yǒu Shí Jiān.", "Chiều nay tôi có thời gian."], [10.403, 13.935, "今天下午我去商店买东西。", "Jīn Tiān Xià Wǔ Wǒ Qù Shāng Diàn Mǎi Dōng Xi.", "Chiều nay tôi đi cửa hàng mua đồ."], [13.935, 16.915, "我跟妈妈一起去商店。", "Wǒ Gēn Mā Ma Yì Qǐ Qù Shāng Diàn.", "Tôi cùng mẹ đi cửa hàng."], [16.936, 19.964, "我想买水和一本书。", "Wǒ Xiǎng Mǎi Shuǐ Hé Yì Běn Shū.", "Tôi muốn mua nước và một quyển sách."], [19.969, 23.093, "商店里有很多学生。", "Shāng Diàn Lǐ Yǒu Hěn Duō Xué Shēng.", "Trong cửa hàng có rất nhiều học sinh."], [23.103, 26.515, "服务员问我：你想买什么？", "Fú Wù Yuán Wèn Wǒ: Nǐ Xiǎng Mǎi Shén Me?", "Nhân viên hỏi tôi: Bạn muốn mua gì?"], [26.515, 29.495, "我说：我先看书。", "Wǒ Shuō: Wǒ Xiān Kàn Shū.", "Tôi nói: Tôi xem sách trước."], [29.503, 32.243, "我先看了一会儿书。", "Wǒ Xiān Kàn Le Yí Huì Er Shū.", "Tôi đọc sách một lát trước."], [32.243, 34.959, "我先买了水和书。", "Wǒ Xiān Mǎi Le Shuǐ Hé Shū.", "Tôi mua nước và sách trước."], [34.969, 37.849, "我再买了三个苹果。", "Wǒ Zài Mǎi Le Sān Gè Píng Guǒ.", "Sau đó tôi mua thêm ba quả táo."], [37.849, 40.733, "苹果一共六块钱。", "Píng Guǒ Yí Gòng Liù Kuài Qián.", "Táo hết sáu đồng."], [40.733, 43.761, "苹果不贵，很便宜。", "Píng Guǒ Bú Guì, Hěn Pián Yi.", "Táo không đắt, rất rẻ."], [43.783, 47.579, "我先看大杯子，再看小杯子。", "Wǒ Xiān Kàn Dà Bēi Zi, Zài Kàn Xiǎo Bēi Zi.", "Tôi xem cái cốc to trước, rồi xem cái cốc nhỏ."], [47.583, 51.451, "妈妈说：这个小杯子很好看。", "Mā Ma Shuō: Zhè Gè Xiǎo Bēi Zi Hěn Hǎo Kàn.", "Mẹ nói: Cái cốc nhỏ này rất đẹp."], [51.483, 54.607, "杯子不大，是白色的。", "Bēi Zi Bù Dà, Shì Bái Sè De.", "Cốc không lớn, màu trắng."], [54.616, 57.256, "我还买了一个杯子。", "Wǒ Hái Mǎi Le Yí Gè Bēi Zi.", "Tôi còn mua một cái cốc."], [57.256, 60.932, "我拿东西回家，爸爸很高兴。", "Wǒ Ná Dōng Xi Huí Jiā, Bà Ba Hěn Gāo Xìng.", "Tôi mang đồ về nhà, bố rất vui."], [60.956, 68.52, "我给妈妈看新杯子，妈妈笑了，说：谢谢你，这个杯子真好看。", "Wǒ Gěi Mā Ma Kàn Xīn Bēi Zi, Mā Ma Xiào Le, Shuō: Xiè Xie Nǐ, Zhè Gè Bēi Zi Zhēn Hǎo Kàn.", "Tôi đưa mẹ xem chiếc cốc mới, mẹ cười và nói: Cảm ơn con, chiếc cốc này thật đẹp."]]}, "hsk1-25": {"dur": 62.32, "cues": [[6.969, 9.709, "我很喜欢学习汉语。", "Wǒ Hěn Xǐ Huan Xué Xí Hàn Yǔ.", "Tôi rất thích học tiếng Trung."], [9.709, 12.469, "我的汉语老师姓张。", "Wǒ De Hàn Yǔ Lǎo Shī Xìng Zhāng.", "Cô giáo tiếng Trung của tôi họ Trương."], [12.469, 15.065, "她教我们说汉语。", "Tā Jiāo Wǒ Men Shuō Hàn Yǔ.", "Cô dạy chúng tôi nói tiếng Trung."], [15.065, 17.445, "她说话很好听。", "Tā Shuō Huà Hěn Hǎo Tīng.", "Cô nói chuyện rất hay."], [17.449, 20.501, "我们每天上午上她的课。", "Wǒ Men Měi Tiān Shàng Wǔ Shàng Tā De Kè.", "Mỗi sáng chúng tôi học tiết của cô."], [20.516, 23.832, "她在教室写汉字给我们看。", "Tā Zài Jiào Shì Xiě Hàn Zì Gěi Wǒ Men Kàn.", "Cô viết chữ Hán trong lớp cho chúng tôi xem."], [23.849, 26.277, "我写汉字不好。", "Wǒ Xiě Hàn Zì Bù Hǎo.", "Tôi viết chữ Hán không tốt."], [26.277, 29.569, "我写得不好，她就帮助我。", "Wǒ Xiě De Bù Hǎo, Tā Jiù Bāng Zhù Wǒ.", "Tôi viết chưa tốt, cô liền giúp tôi."], [29.569, 32.885, "老师教我，我写了三遍。", "Lǎo Shī Jiào Wǒ, Wǒ Xiě Le Sān Biàn.", "Cô dạy tôi, tôi viết ba lần."], [32.889, 35.413, "老师说：很好。", "Lǎo Shī Shuō: Hěn Hǎo.", "Cô nói: Rất tốt."], [35.423, 37.779, "我们都喜欢上课。", "Wǒ Men Dōu Xǐ Huan Shàng Kè.", "Chúng tôi đều thích đi học."], [37.789, 40.913, "下课以后，我说谢谢。", "Xià Kè Yǐ Hòu, Wǒ Shuō Xiè Xie.", "Sau khi tan học, tôi nói cảm ơn."], [40.913, 44.325, "她说不客气，好好学习。", "Tā Shuō Bú Kè Qi, Hǎo Hǎo Xué Xí.", "Cô nói không có gì, hãy học thật chăm."], [44.325, 48.959, "老师笑了，我也笑了。今天的课真好。", "Lǎo Shī Xiào Le, Wǒ Yě Xiào Le. Jīn Tiān De Kè Zhēn Hǎo.", "Cô cười, tôi cũng cười. Buổi học hôm nay thật tuyệt."], [48.959, 52.059, "我很喜欢我的汉语老师。", "Wǒ Hěn Xǐ Huan Wǒ De Hàn Yǔ Lǎo Shī.", "Tôi rất thích cô giáo tiếng Trung của mình."]]}, "hsk1-26": {"dur": 74.84, "cues": [[8.033, 10.989, "今天晚上我们做什么？", "Jīn Tiān Wǎn Shàng Wǒ Men Zuò Shén Me?", "Tối nay chúng ta làm gì?"], [10.989, 14.641, "晚上七点，我在家看电视。", "Wǎn Shàng Qī Diǎn, Wǒ Zài Jiā Kàn Diàn Shì.", "Bảy giờ tối, tôi ở nhà xem ti vi."], [14.643, 17.527, "我想看中国的电影。", "Wǒ Xiǎng Kàn Zhōng Guó De Diàn Yǐng.", "Tôi muốn xem phim Trung Quốc."], [17.527, 20.963, "我说：好，我喜欢。", "Wǒ Shuō: Hǎo, Wǒ Xǐ Huan.", "Tôi nói: Được, tôi thích."], [20.977, 24.245, "爸爸说今天有好电影。", "Bà Ba Shuō Jīn Tiān Yǒu Hǎo Diàn Yǐng.", "Bố nói hôm nay có phim hay."], [24.245, 26.097, "我很高兴。", "Wǒ Hěn Gāo Xìng.", "Tôi rất vui."], [26.11, 29.11, "妈妈做了米饭和鱼。", "Mā Ma Zuò Le Mǐ Fàn Hé Yú.", "Mẹ nấu cơm và cá."], [29.11, 32.066, "米饭和鱼很好吃。", "Mǐ Fàn Hé Yú Hěn Hǎo Chī.", "Cơm và cá rất ngon."], [32.066, 35.382, "我们先吃饭，再看电视。", "Wǒ Men Xiān Chī Fàn, Zài Kàn Diàn Shì.", "Chúng tôi ăn cơm trước, rồi xem ti vi."], [35.41, 37.862, "爸爸说他很累。", "Bà Ba Shuō Tā Hěn Lèi.", "Bố nói bố rất mệt."], [37.877, 40.905, "电视里的电影很好看。", "Diàn Shì Lǐ De Diàn Yǐng Hěn Hǎo Kàn.", "Phim trên ti vi rất hay."], [40.905, 44.149, "我们看到九点，很高兴。", "Wǒ Men Kàn Dào Jiǔ Diǎn, Hěn Gāo Xìng.", "Chúng tôi xem đến chín giờ và rất vui."], [44.177, 46.725, "电影真的很好看。", "Diàn Yǐng Zhēn De Hěn Hǎo Kàn.", "Bộ phim thật sự rất hay."], [46.725, 50.113, "电视说：明天会下雨。", "Diàn Shì Shuō: Míng Tiān Huì Xià Yǔ.", "Ti vi nói: Ngày mai trời sẽ mưa."], [50.113, 53.617, "妈妈说：明天带雨伞吧。", "Mā Ma Shuō: Míng Tiān Dài Yǔ Sǎn Ba.", "Mẹ nói: Ngày mai nhớ mang ô nhé."], [53.617, 57.029, "爸爸说太晚了，要睡觉。", "Bà Ba Shuō Tài Wǎn Le, Yào Shuì Jiào.", "Bố nói đã muộn quá, phải đi ngủ."], [57.029, 60.369, "我说好，明天还上学。", "Wǒ Shuō Hǎo, Míng Tiān Hái Shàng Xué.", "Tôi nói được, ngày mai vẫn đi học."], [60.369, 64.645, "爸爸妈妈都笑了，今天晚上真好。", "Bà Ba Mā Ma Dōu Xiào Le, Jīn Tiān Wǎn Shàng Zhēn Hǎo.", "Bố mẹ đều cười, buổi tối hôm nay thật tuyệt."]]}, "hsk1-27": {"dur": 63.8, "cues": [[6.838, 9.218, "爸爸妈妈在家吗？", "Bà Ba Mā Ma Zài Jiā Ma?", "Bố mẹ có ở nhà không?"], [9.218, 12.218, "上午我给爸爸打电话。", "Shàng Wǔ Wǒ Gěi Bà Ba Dǎ Diàn Huà.", "Sáng tôi gọi điện cho bố."], [12.218, 15.366, "爸爸在家，他说很好。", "Bà Ba Zài Jiā, Tā Shuō Hěn Hǎo.", "Bố ở nhà, ông nói rất khỏe."], [15.385, 17.933, "我问妈妈在家吗。", "Wǒ Wèn Mā Ma Zài Jiā Ma.", "Tôi hỏi mẹ có ở nhà không."], [17.933, 20.937, "爸爸说妈妈去商店了。", "Bà Ba Shuō Mā Ma Qù Shāng Diàn Le.", "Bố nói mẹ đã đi cửa hàng."], [20.951, 23.499, "我想跟妈妈说话。", "Wǒ Xiǎng Gēn Mā Ma Shuō Huà.", "Tôi muốn nói chuyện với mẹ."], [23.518, 26.642, "我说晚上我回家吃饭。", "Wǒ Shuō Wǎn Shàng Wǒ Huí Jiā Chī Fàn.", "Tôi nói tối về nhà ăn cơm."], [26.642, 29.238, "爸爸说他们等我。", "Bà Ba Shuō Tā Men Děng Wǒ.", "Bố nói họ đợi tôi."], [29.251, 32.159, "爸爸说：晚上见。", "Bà Ba Shuō: Wǎn Shàng Jiàn.", "Bố nói: Tối gặp nhé."], [32.185, 35.189, "三点我给妈妈打电话。", "Sān Diǎn Wǒ Gěi Mā Ma Dǎ Diàn Huà.", "Ba giờ tôi gọi điện cho mẹ."], [35.189, 38.289, "我问妈妈：你买了什么？", "Wǒ Wèn Mā Ma: Nǐ Mǎi Le Shén Me?", "Tôi hỏi mẹ: Mẹ mua gì thế?"], [38.289, 41.125, "妈妈买了菜和水果。", "Mā Ma Mǎi Le Cài Hé Shuǐ Guǒ.", "Mẹ mua rau và trái cây."], [41.125, 44.605, "妈妈说她买了苹果和香蕉。", "Mā Ma Shuō Tā Mǎi Le Píng Guǒ Hé Xiāng Jiāo.", "Mẹ nói mẹ đã mua táo và chuối."], [44.605, 48.353, "她说五点回家，我们一起吃饭。", "Tā Shuō Wǔ Diǎn Huí Jiā, Wǒ Men Yì Qǐ Chī Fàn.", "Bà nói năm giờ về nhà, chúng tôi ăn cơm cùng nhau."], [48.353, 53.541, "五点，妈妈回家了。我们一起吃饭，都笑了。", "Wǔ Diǎn, Mā Ma Huí Jiā Le. Wǒ Men Yì Qǐ Chī Fàn, Dōu Xiào Le.", "Năm giờ, mẹ về đến nhà. Cả nhà cùng ăn cơm, ai cũng cười."]]}, "hsk1-28": {"dur": 65.6, "cues": [[7.563, 9.823, "你喜欢小猫吗？", "Nǐ Xǐ Huan Xiǎo Māo Ma?", "Bạn có thích mèo con không?"], [9.823, 13.643, "我有一只白色的猫，它叫小白。", "Wǒ Yǒu Yì Zhī Bái Sè De Māo, Tā Jiào Xiǎo Bái.", "Tôi có một con mèo trắng, tên Tiểu Bạch."], [13.663, 16.571, "它两岁了，很小。", "Tā Liǎng Suì Le, Hěn Xiǎo.", "Nó hai tuổi, rất nhỏ."], [16.571, 18.471, "它很可爱。", "Tā Hěn Kě Ài.", "Nó rất dễ thương."], [18.473, 22.173, "我每天给它喝水，它很高兴。", "Wǒ Měi Tiān Gěi Tā Hē Shuǐ, Tā Hěn Gāo Xìng.", "Mỗi ngày tôi cho nó uống nước, nó rất vui."], [22.173, 25.653, "下午妈妈给它米饭和水。", "Xià Wǔ Mā Ma Gěi Tā Mǐ Fàn Hé Shuǐ.", "Chiều mẹ cho nó ăn cơm và uống nước."], [25.653, 28.873, "我跟小白在家里一起玩儿。", "Wǒ Gēn Xiǎo Bái Zài Jiā Lǐ Yì Qǐ Wán Er.", "Tôi chơi cùng Tiểu Bạch ở nhà."], [28.886, 31.146, "小球跑远了。", "Xiǎo Qiú Pǎo Yuǎn Le.", "Quả bóng lăn đi xa rồi."], [31.146, 34.774, "它喜欢小球，看见就跑。", "Tā Xǐ Huan Xiǎo Qiú, Kàn Jiàn Jiù Pǎo.", "Nó thích quả bóng nhỏ, thấy là chạy."], [34.786, 36.758, "它跑很快。", "Tā Pǎo Hěn Kuài.", "Nó chạy rất nhanh."], [36.758, 40.356, "我也跟它一起跑，我们都很累。", "Wǒ Yě Gēn Tā Yì Qǐ Pǎo, Wǒ Men Dōu Hěn Lèi.", "Tôi cũng chạy theo nó, cả hai đều mệt."], [40.356, 43.264, "晚上它睡在桌子上。", "Wǎn Shàng Tā Shuì Zài Zhuō Zi Shàng.", "Tối nó ngủ trên bàn."], [43.264, 46.268, "它睡觉，我很高兴。", "Tā Shuì Jiào, Wǒ Hěn Gāo Xìng.", "Nó ngủ, tôi rất vui."], [46.29, 49.414, "我说小白是我的好朋友。", "Wǒ Shuō Xiǎo Bái Shì Wǒ De Hǎo Péng Yǒu.", "Tôi nói Tiểu Bạch là bạn tốt của tôi."], [49.414, 55.37, "妈妈说：对，你和小白是好朋友，妈妈很高兴。", "Mā Ma Shuō: Duì, Nǐ Hé Xiǎo Bái Shì Hǎo Péng Yǒu, Mā Ma Hěn Gāo Xìng.", "Mẹ nói: Đúng rồi, con và Tiểu Bạch là bạn tốt, mẹ rất vui."]]}, "hsk1-29": {"dur": 74.03, "cues": [[7.894, 11.306, "商店很大，有好多东西。", "Shāng Diàn Hěn Dà, Yǒu Hǎo Duō Dōng Xi.", "Cửa hàng rất lớn, có rất nhiều đồ."], [11.306, 14.834, "今天下午我在商店买东西。", "Jīn Tiān Xià Wǔ Wǒ Zài Shāng Diàn Mǎi Dōng Xi.", "Chiều nay tôi mua đồ ở cửa hàng."], [14.834, 17.234, "商店里人很多。", "Shāng Diàn Lǐ Rén Hěn Duō.", "Trong cửa hàng có rất nhiều người."], [17.234, 21.244, "我想去厕所，不知道厕所在哪儿。", "Wǒ Xiǎng Qù Cè Suǒ, Bù Zhī Dào Cè Suǒ Zài Nǎ Er.", "Tôi muốn đi nhà vệ sinh nhưng không biết nhà vệ sinh ở đâu."], [21.244, 25.014, "我问人：请问，厕所在哪儿？", "Wǒ Wèn Rén: Qǐng Wèn, Cè Suǒ Zài Nǎ Er?", "Tôi hỏi một người: Xin hỏi, nhà vệ sinh ở đâu?"], [25.014, 27.778, "他说厕所在那边。", "Tā Shuō Cè Suǒ Zài Nà Biān.", "Người đó nói nhà vệ sinh ở phía đó."], [27.78, 31.26, "我说谢谢您，就走过去了。", "Wǒ Shuō Xiè Xie Nín, Jiù Zǒu Guò Qù Le.", "Tôi nói cảm ơn ngài và đi qua."], [31.26, 33.832, "厕所离商店不远。", "Cè Suǒ Lí Shāng Diàn Bù Yuǎn.", "Nhà vệ sinh cách cửa hàng không xa."], [33.832, 36.116, "我觉得很舒服。", "Wǒ Jué De Hěn Shū Fu.", "Tôi cảm thấy rất thoải mái."], [36.127, 38.891, "我回去商店买东西。", "Wǒ Huí Qù Shāng Diàn Mǎi Dōng Xi.", "Tôi quay lại cửa hàng mua đồ."], [38.891, 42.015, "我问服务员：书在哪儿？", "Wǒ Wèn Fú Wù Yuán: Shū Zài Nǎ Ér?", "Tôi hỏi nhân viên: Sách ở đâu?"], [42.015, 45.187, "服务员说：书在那边。", "Fú Wù Yuán Shuō: Shū Zài Nà Biān.", "Nhân viên nói: Sách ở phía đó."], [45.187, 47.999, "我买了茶和一本书。", "Wǒ Mǎi Le Chá Hé Yì Běn Shū.", "Tôi mua trà và một quyển sách."], [48.027, 50.863, "茶很热，我喜欢。", "Chá Hěn Rè, Wǒ Xǐ Huan.", "Trà rất nóng, tôi thích."], [50.863, 53.699, "书不贵，很有用。", "Shū Bú Guì, Hěn Yǒu Yòng.", "Sách không đắt, rất hữu ích."], [53.727, 56.539, "一共花了四十块钱。", "Yí Gòng Huā Le Sì Shí Kuài Qián.", "Tổng cộng hết bốn mươi đồng."], [56.539, 59.591, "我拿好东西，回家了。", "Wǒ Ná Hǎo Dōng Xi, Huí Jiā Le.", "Tôi cầm đồ và về nhà."], [59.591, 63.843, "这本书真好，我看了一会儿，笑了。", "Zhè Běn Shū Zhēn Hǎo, Wǒ Kàn Le Yí Huì Er, Xiào Le.", "Cuốn sách này thật hay, tôi đọc một lúc rồi mỉm cười."]]}, "hsk1-30": {"dur": 67.44, "cues": [[7.661, 10.329, "你明天有时间吗？", "Nǐ Míng Tiān Yǒu Shí Jiān Ma?", "Ngày mai bạn có thời gian không?"], [10.329, 12.973, "明天是我的生日。", "Míng Tiān Shì Wǒ De Shēng Rì.", "Ngày mai là sinh nhật của tôi."], [12.973, 18.329, "我对妈妈说：明天请朋友来我家，好吗？", "Wǒ Duì Mā Ma Shuō: Míng Tiān Qǐng Péng Yǒu Lái Wǒ Jiā, Hǎo Ma?", "Tôi nói với mẹ: Ngày mai mời bạn đến nhà mình nhé, được không mẹ?"], [18.361, 21.413, "妈妈笑了，她说好。", "Mā Ma Xiào Le, Tā Shuō Hǎo.", "Mẹ cười, mẹ nói được."], [21.428, 24.648, "妈妈说明天她不出门。", "Mā Ma Shuō Míng Tiān Tā Bù Chū Mén.", "Mẹ nói ngày mai bà không ra ngoài."], [24.661, 27.737, "爸爸要去商店买东西。", "Bà Ba Yào Qù Shāng Diàn Mǎi Dōng Xi.", "Bố sẽ đi cửa hàng mua đồ."], [27.737, 31.149, "他想买很多水果和鸡蛋。", "Tā Xiǎng Mǎi Hěn Duō Shuǐ Guǒ Hé Jī Dàn.", "Ông muốn mua nhiều trái cây và trứng."], [31.161, 34.261, "我喜欢吃水果和鸡蛋。", "Wǒ Xǐ Huan Chī Shuǐ Guǒ Hé Jī Dàn.", "Tôi thích ăn trái cây và trứng."], [34.261, 37.337, "我的朋友小王要来我家。", "Wǒ De Péng Yǒu Xiǎo Wáng Yào Lái Wǒ Jiā.", "Bạn Tiểu Vương của tôi sẽ đến nhà."], [37.337, 40.293, "小王是我的好同学。", "Xiǎo Wáng Shì Wǒ De Hǎo Tóng Xué.", "Tiểu Vương là bạn học tốt của tôi."], [40.294, 42.914, "我给小王打电话。", "Wǒ Gěi Xiǎo Wáng Dǎ Diàn Huà.", "Tôi gọi điện cho Tiểu Vương."], [42.914, 45.846, "小王说：明天见。", "Xiǎo Wáng Shuō: Míng Tiān Jiàn.", "Tiểu Vương nói: Mai gặp lại nhé."], [45.861, 49.033, "妈妈要做很多饭和菜。", "Mā Ma Yào Zuò Hěn Duō Fàn Hé Cài.", "Mẹ sẽ nấu nhiều cơm và món ăn."], [49.033, 54.629, "我跟妈妈说：谢谢妈妈。妈妈笑了，我也笑了。", "Wǒ Gēn Mā Ma Shuō: Xiè Xie Mā Ma. Mā Ma Xiào Le, Wǒ Yě Xiào Le.", "Tôi nói với mẹ: Cảm ơn mẹ. Mẹ cười, tôi cũng cười."], [54.631, 57.155, "晚上我好好睡觉。", "Wǎn Shàng Wǒ Hǎo Hǎo Shuì Jiào.", "Tối tôi ngủ thật ngoan."]]}};
